import math
import random

def color_graph(adj: list[list[int]]) -> list[int]:
    if not adj:
        return []
    n = len(adj)
    if n == 1:
        return [0]

    # Detect input format: adjacency matrix if square and binary
    is_matrix = False
    if n > 0 and len(adj[0]) == n:
        if all(isinstance(x, int) and x in (0, 1) for row in adj for x in row):
            is_matrix = True

    # Build neighbor sets for efficient access (undirected, no self-loops)
    neighbors = [set() for _ in range(n)]
    if is_matrix:
        for i in range(n):
            for j in range(n):
                if adj[i][j] == 1 and i != j:
                    neighbors[i].add(j)
    else:
        for i in range(n):
            for j in adj[i]:
                if 0 <= j < n and i != j:
                    neighbors[i].add(j)

    # Ensure symmetry (undirected graph)
    for i in range(n):
        for j in list(neighbors[i]):
            if i not in neighbors[j]:
                neighbors[j].add(i)

    # Trivial cases
    if all(len(neighbors[i]) == 0 for i in range(n)):
        return [0] * n
    if all(len(neighbors[i]) == n - 1 for i in range(n)):
        return list(range(n))

    # Precompute degrees
    degrees = [len(neighbors[i]) for i in range(n)]

    # Helper: greedy coloring with given vertex order
    def greedy_color(order):
        coloring = [-1] * n
        for v in order:
            used = [False] * n
            for u in neighbors[v]:
                if coloring[u] != -1:
                    used[coloring[u]] = True
            c = 0
            while c < n and used[c]:
                c += 1
            coloring[v] = c
        return coloring

    # Helper: validate coloring
    def is_valid(coloring):
        for u in range(n):
            cu = coloring[u]
            for v in neighbors[u]:
                if cu == coloring[v]:
                    return False
        return True

    # Helper: degeneracy ordering (smallest-last) using bucket sort for O(n + m)
    def degeneracy_ordering():
        deg = degrees[:]  # current degree in remaining subgraph
        removed = [False] * n
        order = []
        max_deg = max(deg) if n > 0 else 0
        # Bucket initialization
        buckets = [[] for _ in range(max_deg + 1)]
        for v in range(n):
            if deg[v] < len(buckets):
                buckets[deg[v]].append(v)
        # Process buckets
        for d in range(max_deg + 1):
            while buckets[d]:
                v = buckets[d].pop()
                if removed[v]:
                    continue
                if deg[v] != d:  # outdated degree, rebucket
                    if deg[v] < len(buckets):
                        buckets[deg[v]].append(v)
                    continue
                removed[v] = True
                order.append(v)
                for u in neighbors[v]:
                    if not removed[u]:
                        if deg[u] > d:
                            deg[u] -= 1
                            if deg[u] < len(buckets):
                                buckets[deg[u]].append(u)
        return order[::-1]  # reverse for smallest-last order

    # Helper: DSATUR coloring with optional initial order (optimized)
    def dsatur_coloring(order=None):
        coloring = [-1] * n
        if order is None:
            # Default order: degree descending
            order = sorted(range(n), key=lambda x: degrees[x], reverse=True)
        # Saturation sets: track distinct colors in neighbors
        saturation = [set() for _ in range(n)]
        uncolored = set(range(n))
        # Maintain list of uncolored vertices by saturation degree for efficiency
        # We use buckets for saturation degree (0..n)
        max_sat = n
        sat_buckets = [[] for _ in range(max_sat + 1)]
        for v in range(n):
            sat_buckets[0].append(v)
        # Current saturation degree for each vertex
        sat_deg = [0] * n

        # Process vertices by dynamic saturation selection
        for _ in range(n):
            # Find the highest non-empty saturation bucket
            v = -1
            for s in range(max_sat, -1, -1):
                # Find an uncolored vertex in bucket s
                while sat_buckets[s]:
                    u = sat_buckets[s].pop()
                    if u in uncolored and sat_deg[u] == s:
                        v = u
                        break
                if v != -1:
                    break
            if v == -1:
                # Fallback: linear scan (should rarely happen)
                max_sat_val = -1
                for u in uncolored:
                    if sat_deg[u] > max_sat_val:
                        max_sat_val = sat_deg[u]
                        v = u
                    elif sat_deg[u] == max_sat_val and u < v:
                        v = u

            # Find smallest available color (MEX)
            used = saturation[v]
            c = 0
            while c in used:
                c += 1
            coloring[v] = c

            # Update saturation of uncolored neighbors
            uncolored.remove(v)
            for u in neighbors[v]:
                if u in uncolored:
                    old_sat = sat_deg[u]
                    saturation[u].add(c)
                    new_sat = len(saturation[u])
                    sat_deg[u] = new_sat
                    if new_sat > old_sat:
                        sat_buckets[new_sat].append(u)
        return coloring

    # Helper: Kempe chain-based color reduction (optimized with early termination)
    def kempe_reduce(coloring):
        if n == 0:
            return coloring
        max_color = max(coloring)
        if max_color < 0:
            return coloring

        # Try to eliminate color classes from highest down
        for target_color in range(max_color, 0, -1):
            # Vertices currently colored with target_color
            target_vertices = [v for v in range(n) if coloring[v] == target_color]
            if not target_vertices:
                continue  # already eliminated

            changed = False
            for v in target_vertices:
                # Colors used by neighbors
                neighbor_colors = {coloring[u] for u in neighbors[v]}
                # Try direct reassignment to a free lower color
                for c in range(target_color):
                    if c not in neighbor_colors:
                        coloring[v] = c
                        changed = True
                        break
                if changed:
                    break  # restart target_color scan after change

                # Try Kempe chains for each lower color c not in neighbor_colors
                for c in range(target_color):
                    if c in neighbor_colors:
                        continue  # direct move blocked, but Kempe might still help if we can swap to free c
                    # Find the (c, target_color)-Kempe chain component containing v using iterative DFS
                    stack = [v]
                    visited = [False] * n
                    visited[v] = True
                    component = []
                    while stack:
                        node = stack.pop()
                        component.append(node)
                        for nb in neighbors[node]:
                            if not visited[nb] and (coloring[nb] == c or coloring[nb] == target_color):
                                visited[nb] = True
                                stack.append(nb)
                    # Swap colors c and target_color in the component
                    for node in component:
                        if coloring[node] == c:
                            coloring[node] = target_color
                        elif coloring[node] == target_color:
                            coloring[node] = c
                    changed = True
                    break  # break c-loop after successful swap
                if changed:
                    break  # break v-loop after change
            if not changed:
                # Could not eliminate this color class; stop reduction
                break
        return coloring

    # Generate candidate colorings from multiple heuristics
    candidates = []

    # 1. Welsh-Powell (degree ordering + First-Fit)
    order_wp = sorted(range(n), key=lambda x: degrees[x], reverse=True)
    candidates.append(greedy_color(order_wp))

    # 2. Smallest-Last (degeneracy ordering)
    order_sl = degeneracy_ordering()
    candidates.append(greedy_color(order_sl))

    # 3. DSATUR with default ordering
    candidates.append(dsatur_coloring())

    # 4. DSATUR with degeneracy ordering
    candidates.append(dsatur_coloring(order_sl))

    # Apply Kempe reduction to each candidate
    for i in range(len(candidates)):
        candidates.append(kempe_reduce(candidates[i][:]))  # work on a copy

    # Additionally, try a few random greedy orders with Kempe refinement (limited for speed)
    for _ in range(2):  # Reduced to 2 to ensure <50ms
        order = list(range(n))
        random.shuffle(order)
        cand = greedy_color(order)
        candidates.append(cand)
        candidates.append(kempe_reduce(cand[:]))

    # Select the valid coloring with the fewest colors
    best_coloring = None
    best_num_colors = float('inf')
    for col in candidates:
        if is_valid(col):
            num_colors = len(set(col))
            if num_colors < best_num_colors:
                best_num_colors = num_colors
                best_coloring = col

    # Fallback: should not happen, but greedy in natural order
    if best_coloring is None:
        best_coloring = greedy_color(list(range(n)))

    return best_coloring

