import math
import random

def color_graph(adj: list[list[int]]) -> list[int]:
    n = len(adj)
    if n == 0:
        return []

    # Detect adjacency matrix
    is_matrix = False
    if n > 0 and len(adj[0]) == n:
        is_matrix = True
        for i in range(n):
            if len(adj[i]) != n:
                is_matrix = False
                break
            for val in adj[i]:
                if val not in (0, 1):
                    is_matrix = False
                    break
            if not is_matrix:
                break

    # Build adjacency list
    if is_matrix:
        neighbors = []
        for i in range(n):
            nbrs = [j for j in range(n) if adj[i][j] == 1]
            neighbors.append(nbrs)
    else:
        neighbors = adj

    deg = [len(neighbors[i]) for i in range(n)]

    # Trivial cases
    if all(d == 0 for d in deg):
        return [0] * n

    is_complete = True
    for i in range(n):
        if deg[i] != n - 1:
            is_complete = False
            break
    if is_complete:
        return list(range(n))

    # Helper: greedy coloring with given order
    def greedy_color(order):
        color = [-1] * n
        for v in order:
            used = [False] * n
            for u in neighbors[v]:
                if color[u] != -1:
                    used[color[u]] = True
            c = 0
            while c < n and used[c]:
                c += 1
            color[v] = c
        return color

    # DSATUR implementation
    def dsatur():
        color = [-1] * n
        saturation = [set() for _ in range(n)]
        uncolored = set(range(n))

        while uncolored:
            best_v = -1
            best_sat = -1
            best_deg = -1
            for v in uncolored:
                sat_v = len(saturation[v])
                deg_uncolored = sum(1 for u in neighbors[v] if u in uncolored)
                if sat_v > best_sat or (sat_v == best_sat and deg_uncolored > best_deg) or \
                   (sat_v == best_sat and deg_uncolored == best_deg and random.random() < 0.5):
                    best_sat = sat_v
                    best_deg = deg_uncolored
                    best_v = v
            v = best_v
            used = [False] * n
            for u in neighbors[v]:
                if color[u] != -1:
                    used[color[u]] = True
            c = 0
            while c < n and used[c]:
                c += 1
            color[v] = c
            uncolored.remove(v)
            for u in neighbors[v]:
                if u in uncolored:
                    saturation[u].add(c)
        return color

    # Independent Set Extraction with DSATUR-inspired ordering (RLF-DSATUR hybrid)
    def rlf_dsatur_hybrid():
        color = [-1] * n
        uncolored = set(range(n))
        c = 0
        while uncolored:
            # Compute degrees in the uncolored subgraph
            deg_uncolored = [0] * n
            for v in uncolored:
                for u in neighbors[v]:
                    if u in uncolored:
                        deg_uncolored[v] += 1
            # Select start vertex: max degree in uncolored subgraph
            start = max(uncolored, key=lambda v: deg_uncolored[v])
            S = [start]
            U = uncolored - {start}
            W = set()
            for u in neighbors[start]:
                if u in uncolored:
                    W.add(u)
            U -= W

            # Construct independent set S with DSATUR-inspired vertex selection
            while U:
                best_u = -1
                best_score = -1
                best_sat = -1
                best_deg_U = -1
                for u in U:
                    # Score: number of neighbors in W (as in RLF)
                    score = sum(1 for w in neighbors[u] if w in W)
                    # Saturation degree: number of distinct colors in neighbors (from colored vertices)
                    sat_u = len({color[w] for w in neighbors[u] if color[w] != -1})
                    # Degree in U: for tie-breaking
                    deg_u = sum(1 for w in neighbors[u] if w in U)
                    # Primary: maximize score (neighbors in W)
                    # Secondary: maximize saturation degree (DSATUR influence)
                    # Tertiary: minimize degree in U (to leave U less constrained)
                    # Quaternary: random tie-break
                    if (score > best_score or 
                        (score == best_score and sat_u > best_sat) or
                        (score == best_score and sat_u == best_sat and deg_u < best_deg_U) or
                        (score == best_score and sat_u == best_sat and deg_u == best_deg_U and random.random() < 0.5)):
                        best_score = score
                        best_sat = sat_u
                        best_deg_U = deg_u
                        best_u = u
                u = best_u
                S.append(u)
                U.remove(u)
                # Move neighbors of u from U to W
                for w in neighbors[u]:
                    if w in U:
                        U.remove(w)
                        W.add(w)
            # Assign color c to all vertices in S
            for v in S:
                color[v] = c
            uncolored -= set(S)
            c += 1
        return color

    # Welsh-Powell
    def welsh_powell():
        order = sorted(range(n), key=lambda v: deg[v], reverse=True)
        return greedy_color(order)

    # Smallest-Last ordering
    def smallest_last():
        if n == 0:
            return []
        max_deg = max(deg) if n > 0 else 0
        degree = deg[:]
        removed = [False] * n
        bins = [[] for _ in range(max_deg + 1)]
        for v in range(n):
            d = degree[v]
            bins[d].append(v)
        ptr = 0
        order = []
        for _ in range(n):
            while ptr <= max_deg and not bins[ptr]:
                ptr += 1
            if ptr > max_deg:
                break
            v = bins[ptr].pop()
            removed[v] = True
            order.append(v)
            for u in neighbors[v]:
                if not removed[u]:
                    d_u = degree[u]
                    # remove u from bins[d_u]
                    if u in bins[d_u]:
                        bins[d_u].remove(u)
                    degree[u] -= 1
                    bins[d_u - 1].append(u)
                    if d_u - 1 < ptr:
                        ptr = d_u - 1
        return greedy_color(order[::-1])

    # Candidate heuristics
    candidates = [dsatur(), rlf_dsatur_hybrid(), welsh_powell(), smallest_last()]

    # Select best valid candidate
    best_color = None
    best_k = float('inf')
    for col in candidates:
        valid = True
        for u in range(n):
            for v in neighbors[u]:
                if col[u] == col[v]:
                    valid = False
                    break
            if not valid:
                break
        if not valid:
            continue
        k = max(col) + 1 if n > 0 else 0
        if k < best_k:
            best_k = k
            best_color = col

    if best_color is None:
        best_color = greedy_color(list(range(n)))

    # Kempe chain refinement
    def kempe_reduce(coloring):
        col = coloring[:]
        changed = True
        while changed:
            changed = False
            max_color = max(col) if n > 0 else -1
            if max_color < 0:
                return col
            classes = [set() for _ in range(max_color + 1)]
            for v in range(n):
                classes[col[v]].add(v)
            # Try to eliminate highest color class
            for target_color in range(max_color, -1, -1):
                if not classes[target_color]:
                    continue
                made_change = False
                for v in list(classes[target_color]):
                    for c in range(target_color):
                        conflict = False
                        for u in neighbors[v]:
                            if col[u] == c:
                                conflict = True
                                break
                        if not conflict:
                            classes[target_color].remove(v)
                            classes[c].add(v)
                            col[v] = c
                            made_change = True
                            changed = True
                            break
                    if made_change:
                        break
                if made_change:
                    break
            # Kempe chains for highest color
            if not changed and max_color >= 0:
                target_color = max_color
                if not classes[target_color]:
                    return col
                for v in list(classes[target_color]):
                    for c in range(target_color):
                        adjacent_to_c = any(col[u] == c for u in neighbors[v])
                        if not adjacent_to_c:
                            continue
                        # Build component of v in (target_color, c) subgraph
                        comp = set()
                        stack = [v]
                        comp.add(v)
                        while stack:
                            x = stack.pop()
                            for y in neighbors[x]:
                                if col[y] == target_color or col[y] == c:
                                    if y not in comp:
                                        comp.add(y)
                                        stack.append(y)
                        # Check if any vertex in comp of color c has external neighbor of target_color
                        has_external = False
                        for x in comp:
                            if col[x] == c:
                                for y in neighbors[x]:
                                    if col[y] == target_color and y not in comp:
                                        has_external = True
                                        break
                                if has_external:
                                    break
                        if not has_external:
                            # Swap colors in component
                            for x in comp:
                                if col[x] == target_color:
                                    col[x] = c
                                else:
                                    col[x] = target_color
                            classes[target_color] -= comp
                            classes[c] |= comp
                            changed = True
                            break
                    if changed:
                        break
                if changed:
                    break
        return col

    refined = kempe_reduce(best_color)
    # Validate refined coloring
    valid = True
    for u in range(n):
        for v in neighbors[u]:
            if refined[u] == refined[v]:
                valid = False
                break
        if not valid:
            break
    if valid:
        return refined
    else:
        return best_color
